impl < I : Idx , T > IndexSlice < I , T > { # [inline] pub const fn empty < 'a > () -> & 'a Self { Self :: from_raw (& []) } # [inline] pub const fn from_raw (raw : & [T]) -> & Self { let ptr : * const [T] = raw ; unsafe { & * (ptr as * const Self) } } # [inline] pub fn from_raw_mut (raw : & mut [T]) -> & mut Self { let ptr : * mut [T] = raw ; unsafe { & mut * (ptr as * mut Self) } } # [inline] pub const fn len (& self) -> usize { self . raw . len () } # [inline] pub const fn is_empty (& self) -> bool { self . raw . is_empty () } # [doc = " Gives the next index that will be assigned when `push` is called."] # [doc = ""] # [doc = " Manual bounds checks can be done using `idx < slice.next_index()`"] # [doc = " (as opposed to `idx.index() < slice.len()`)."] # [inline] pub fn next_index (& self) -> I { I :: new (self . len ()) } # [inline] pub fn iter (& self) -> slice :: Iter < '_ , T > { self . raw . iter () } # [inline] pub fn iter_enumerated (& self) -> impl DoubleEndedIterator < Item = (I , & T) > + ExactSizeIterator { let _ = I :: new (self . len ()) ; self . raw . iter () . enumerate () . map (| (n , t) | (I :: new (n) , t)) } # [inline] pub fn indices (& self ,) -> impl DoubleEndedIterator < Item = I > + ExactSizeIterator + Clone + 'static { let _ = I :: new (self . len ()) ; (0 .. self . len ()) . map (| n | I :: new (n)) } # [inline] pub fn iter_mut (& mut self) -> slice :: IterMut < '_ , T > { self . raw . iter_mut () } # [inline] pub fn iter_enumerated_mut (& mut self ,) -> impl DoubleEndedIterator < Item = (I , & mut T) > + ExactSizeIterator { let _ = I :: new (self . len ()) ; self . raw . iter_mut () . enumerate () . map (| (n , t) | (I :: new (n) , t)) } # [inline] pub fn last_index (& self) -> Option < I > { self . len () . checked_sub (1) . map (I :: new) } # [inline] pub fn swap (& mut self , a : I , b : I) { self . raw . swap (a . index () , b . index ()) } # [inline] pub fn copy_within (& mut self , src : impl IntoSliceIdx < I , [T] , Output : RangeBounds < usize > > , dest : I ,) where T : Copy , { self . raw . copy_within (src . into_slice_idx () , dest . index ()) ; } # [inline] pub fn get < R : IntoSliceIdx < I , [T] > > (& self , index : R ,) -> Option < & < R :: Output as SliceIndex < [T] > > :: Output > { self . raw . get (index . into_slice_idx ()) } # [inline] pub fn get_mut < R : IntoSliceIdx < I , [T] > > (& mut self , index : R ,) -> Option < & mut < R :: Output as SliceIndex < [T] > > :: Output > { self . raw . get_mut (index . into_slice_idx ()) } # [doc = " Returns mutable references to two distinct elements, `a` and `b`."] # [doc = ""] # [doc = " Panics if `a == b` or if some of them are out of bounds."] # [inline] pub fn pick2_mut (& mut self , a : I , b : I) -> (& mut T , & mut T) { let (ai , bi) = (a . index () , b . index ()) ; match self . raw . get_disjoint_mut ([ai , bi]) { Ok ([a , b]) => (a , b) , Err (OverlappingIndices) => panic ! ("Indices {ai:?} and {bi:?} are not disjoint!") , Err (IndexOutOfBounds) => { panic ! ("Some indices among ({ai:?}, {bi:?}) are out of bounds") } } } # [doc = " Returns mutable references to three distinct elements."] # [doc = ""] # [doc = " Panics if the elements are not distinct or if some of them are out of bounds."] # [inline] pub fn pick3_mut (& mut self , a : I , b : I , c : I) -> (& mut T , & mut T , & mut T) { let (ai , bi , ci) = (a . index () , b . index () , c . index ()) ; match self . raw . get_disjoint_mut ([ai , bi , ci]) { Ok ([a , b , c]) => (a , b , c) , Err (OverlappingIndices) => { panic ! ("Indices {ai:?}, {bi:?} and {ci:?} are not disjoint!") } Err (IndexOutOfBounds) => { panic ! ("Some indices among ({ai:?}, {bi:?}, {ci:?}) are out of bounds") } } } # [inline] pub fn binary_search (& self , value : & T) -> Result < I , I > where T : Ord , { match self . raw . binary_search (value) { Ok (i) => Ok (Idx :: new (i)) , Err (i) => Err (Idx :: new (i)) , } } }